-- 14-play-participants. Reviewed uploaded workbook only; save pending edits and back up first.
-- Run ENTIRE file in DB Browser, verify counts, then Write Changes.
-- SAVEPOINT supports an existing transaction. No records are replaced.
-- No Home/Away/NA fake players; participant teams come from play roles.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_14;
CREATE TEMP TABLE afl_remaining_14_0 AS SELECT id, play_id, player_id, team_id, role, position_slot, participation_source FROM play_participants WHERE 0;
CREATE TEMP TABLE afl_remaining_14_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_remaining_14_check BEFORE INSERT ON afl_remaining_14_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import 05 season first.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2) THEN RAISE(ROLLBACK,'Apply schema upgrade 10 first.') END;
 SELECT CASE WHEN (SELECT count(*) FROM plays WHERE game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258'))<>9575 THEN RAISE(ROLLBACK,'Import all official plays (12) first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_14_0 i JOIN play_participants t ON t.id=i.id WHERE t.play_id IS NOT i.play_id OR t.player_id IS NOT i.player_id OR t.team_id IS NOT i.team_id OR t.role IS NOT i.role OR t.position_slot IS NOT i.position_slot OR t.participation_source IS NOT i.participation_source) THEN RAISE(ROLLBACK,'play_participants: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_14_0 i JOIN play_participants t ON t.play_id=i.play_id AND t.player_id IS i.player_id AND t.team_id=i.team_id AND t.role=i.role WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'play_participants: natural key uses another ID.') END;
END;
DROP TRIGGER afl_remaining_14_check;
DROP TABLE afl_remaining_14_guard;
DROP TABLE afl_remaining_14_0;
RELEASE SAVEPOINT afl_remaining_14;
PRAGMA foreign_key_check;
SELECT 'play_participants' AS imported_table,count(*) AS reviewed_records_present FROM play_participants t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='0236be72-01b6-5988-b1a1-ba2fa38469c1' AND m.target_table='play_participants' AND m.target_id=CAST(t.id AS TEXT));
